"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["21479"],{97504(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.calendario_dias_uteis_congelado.sem_dia_nao_util","status":422,"titulo":"O calend\xe1rio congelado precisa ter ao menos um dia n\xe3o \xfatil"},"descricao":{"codigo":"uniplus.selecao.calendario_dias_uteis_congelado.sem_dia_nao_util","requisitos":["UNI-REQ-0080"],"oQueAconteceu":["O calend\xe1rio de dias \xfateis vigente n\xe3o traz nenhum dia n\xe3o \xfatil. Um calend\xe1rio vazio n\xe3o conta\\nnada: congel\xe1-lo faria a vers\xe3o afirmar que todo dia \xe9 \xfatil, e a contagem do prazo de recurso\\nproduziria um instante diferente do calend\xe1rio que rege o certame, de forma imut\xe1vel e sem nada\\nque acusasse.","O calend\xe1rio de dias \xfateis vigente \xe9 cadastrado no m\xf3dulo Configura\xe7\xe3o, e a vers\xe3o do processo\\ncongela uma c\xf3pia dele por valor, com a lista dos dias n\xe3o \xfateis (UNI-REQ-0080). Ao copi\xe1-lo, o\\nsistema confere de novo cada dia e o conjunto, e recusa o que o cadastro n\xe3o aceitaria. A recusa\\ns\xf3 vale para o processo que depende do calend\xe1rio, isto \xe9, o que tem prazo de recurso (ver\\n[calend\xe1rio vigente ausente](/erros/uniplus.selecao.processo_seletivo.calendario_vigente_ausente)); um processo sem contagem sobre dia \xfatil segue normalmente, porque n\xe3o usa o dado.","A confer\xeancia vem depois das da localidade ([`localidade_ausente`](/erros/uniplus.selecao.processo_seletivo.localidade_ausente)) e da conven\xe7\xe3o de contagem\\n([`algoritmo_contagem_prazo_nao_declarado`](/erros/uniplus.selecao.processo_seletivo.algoritmo_contagem_prazo_nao_declarado)), e antes das demais confer\xeancias de conformidade e do cronograma. A consulta de\\nconformidade do processo mostra o item \\"Calend\xe1rio de dias \xfateis vigente\\" como pendente enquanto o\\ncalend\xe1rio vigente estiver nessa condi\xe7\xe3o. Nada \xe9 gravado.","Esta confer\xeancia vem depois das do identificador e da vers\xe3o do calend\xe1rio e antes da do dia\\nrepetido ([`dia_duplicado`](/erros/uniplus.selecao.calendario_dias_uteis_congelado.dia_duplicado))."],"comoResolver":["A causa n\xe3o est\xe1 na configura\xe7\xe3o do processo, e nada nela corrige a recusa: o dado vem do\\ncalend\xe1rio de dias \xfateis vigente, cadastrado no m\xf3dulo Configura\xe7\xe3o. Como a vers\xe3o publicada\\ncongela o calend\xe1rio por valor, a corre\xe7\xe3o \xe9 na origem, antes de publicar ou retificar:\\ncadastre um calend\xe1rio (dataset) corrigido, que o cadastro confere ao criar, coloque-o em vig\xeancia\\ne repita a opera\xe7\xe3o.","O cadastro recusa o calend\xe1rio sem dia n\xe3o \xfatil ao cri\xe1-lo ([`sem_dia_nao_util`](/erros/uniplus.configuracao.calendario_dias_uteis.sem_dia_nao_util)). Um\\ncalend\xe1rio vigente nessa condi\xe7\xe3o indica dado gravado por caminho que n\xe3o passou por essa\\nconfer\xeancia, e a causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Calendario dias uteis congelado"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);